SCRIPT = """<script>
const I18N=%s;
let lang='id'; try{ const s=localStorage.getItem('loop-mcu-lang'); if(s==='en'||s==='id') lang=s; }catch(e){}
const $=id=>document.getElementById(id);
function applyLang(){ document.documentElement.lang=lang; const d=I18N[lang]; document.querySelectorAll('[data-i18n]').forEach(el=>{ const v=d[el.dataset.i18n]; if(typeof v==='string') el.innerHTML=v; }); document.querySelectorAll('[data-i18n-ph]').forEach(el=>{ const v=d[el.dataset.i18nPh]; if(typeof v==='string') el.placeholder=v; }); $('langId').setAttribute('aria-pressed',lang==='id'); $('langEn').setAttribute('aria-pressed',lang==='en'); }
function setLang(l){ lang=l; try{ localStorage.setItem('loop-mcu-lang',l); }catch(e){} applyLang(); }
$('langId').addEventListener('click',()=>setLang('id')); $('langEn').addEventListener('click',()=>setLang('en')); applyLang();
%s
</script>"""

def page(filename, title, active, body, i18n, extra_js=""):
    merged = {L: {**SHARED_I18N[L], **i18n.get(L, {})} for L in ("id","en")}
    doc = f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{title}</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Fraunces:ital,opsz,wght@0,9..144,500..700;1,9..144,400..600&display=swap"><style>{CSS}</style></head><body>
{header(active)}
{body}
{footer()}
{SCRIPT % (json.dumps(merged, ensure_ascii=False), extra_js)}
</body></html>'''
    open(os.path.join(OUT, filename), "w").write(doc)
    used = set(re.findall(r'data-i18n(?:-ph)?="([^"]+)"', doc))
    missing = [k for k in used if k not in merged["id"] or k not in merged["en"]]
    assert not missing, (filename, missing)
    print("built", filename, len(doc), "chars,", len(used), "keys")

