HERO_PIC = {"cor": ("loop-kit.png","Loop Kit untuk karyawan","contain"), "ins": ("mockup.png","Aplikasi Loop: data gula darah member","contain")}
QUOTE_AV = {"per": [("member-lilis.png","Lilis Suryani",False),("member-zulkarnain.png","Zulkarnain",False),("member-lenny.png","Lenny Kristiani",False)],
            "cor": [("lontar.svg","Lontar Papyrus",True),("ikpp.svg","Indah Kiat",True),("mqare.svg","mQare",True)], "ins": [None,None,None]}
def audience(filename, active, key, funnel, title):
    body = f'''<section class="hero bleed"><div class="wrap"><div><span class="eyebrow" data-i18n="{key}.eye"></span><h1 data-i18n="{key}.h1"></h1><p class="lead" data-i18n="{key}.lead"></p>
<div class="cta"><a class="btn primary" href="{funnel}" data-i18n="{key}.cta1"></a><a class="btn ghost" href="konsultasi.html" data-i18n="{key}.cta2"></a></div>
<div class="trust"><div><b data-i18n="{key}.t1b"></b><span data-i18n="{key}.t1s"></span></div><div><b data-i18n="{key}.t2b"></b><span data-i18n="{key}.t2s"></span></div><div><b data-i18n="{key}.t3b"></b><span data-i18n="{key}.t3s"></span></div></div></div>
{preview_card() if key=="per" else pic(HERO_PIC[key][0], HERO_PIC[key][1], HERO_PIC[key][2])}</div></section>
<div class="wrap">
<section class="sec"><div class="split"><div><span class="eyebrow" data-i18n="{key}.w.eye"></span><h2 data-i18n="{key}.w.h"></h2><p class="lead" data-i18n="{key}.w.p"></p><a class="btn primary" href="{funnel}" data-i18n="{key}.cta1"></a></div>
<div class="grid3" style="grid-template-columns:1fr"><div class="card step"><div class="n">1</div><h3 data-i18n="{key}.w.1h"></h3><p data-i18n="{key}.w.1p"></p></div><div class="card step"><div class="n">2</div><h3 data-i18n="{key}.w.2h"></h3><p data-i18n="{key}.w.2p"></p></div><div class="card step"><div class="n">3</div><h3 data-i18n="{key}.w.3h"></h3><p data-i18n="{key}.w.3p"></p></div></div></div></section>
<section class="sec center"><span class="eyebrow" data-i18n="{key}.f.eye"></span><h2 data-i18n="{key}.f.h"></h2><p class="lead" data-i18n="{key}.f.p"></p>
<div class="grid4" style="text-align:left"><div class="card feat"><div class="ic">1</div><h3 data-i18n="{key}.f.1h"></h3><p data-i18n="{key}.f.1p"></p></div><div class="card feat"><div class="ic">2</div><h3 data-i18n="{key}.f.2h"></h3><p data-i18n="{key}.f.2p"></p></div><div class="card feat"><div class="ic">3</div><h3 data-i18n="{key}.f.3h"></h3><p data-i18n="{key}.f.3p"></p></div><div class="card feat"><div class="ic">4</div><h3 data-i18n="{key}.f.4h"></h3><p data-i18n="{key}.f.4p"></p></div></div></section>
</div>
<section class="dark bleed" style="margin-top:88px"><div class="wrap"><span class="eyebrow" style="color:var(--teal)" data-i18n="{key}.q.eye"></span><h2 data-i18n="{key}.q.h"></h2>
<div class="grid3"><div class="card quote">{av(*QUOTE_AV[key][0]) if QUOTE_AV[key][0] else ""}<span class="badge" data-i18n="{key}.q.1b"></span><div class="delta" data-i18n="{key}.q.1d"></div><div class="who" data-i18n="{key}.q.1w"></div><p data-i18n="{key}.q.1q"></p></div><div class="card quote">{av(*QUOTE_AV[key][1]) if QUOTE_AV[key][1] else ""}<span class="badge" data-i18n="{key}.q.2b"></span><div class="delta" data-i18n="{key}.q.2d"></div><div class="who" data-i18n="{key}.q.2w"></div><p data-i18n="{key}.q.2q"></p></div><div class="card quote">{av(*QUOTE_AV[key][2]) if QUOTE_AV[key][2] else ""}<span class="badge" data-i18n="{key}.q.3b"></span><div class="delta" data-i18n="{key}.q.3d"></div><div class="who" data-i18n="{key}.q.3w"></div><p data-i18n="{key}.q.3q"></p></div></div></div></section>
<div class="wrap"><section class="sec"><div class="card" style="display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center;background:var(--mint);border:0"><div><h3 style="font-size:22px" data-i18n="{key}.rep.h"></h3><p style="margin:0" data-i18n="{key}.rep.p"></p></div><a class="btn primary" href="{funnel}#example" data-i18n="{key}.rep.c"></a></div></section></div>
<div style="margin-top:88px">{band(f"{key}.band.h",f"{key}.band.p","band.c1",funnel,"band.c2",WA)}</div>'''
    return body

